dslRule:
new java.lang.RuntimeException()
=> new java.lang.RuntimeException("Unnamed runtime exception")
;;

beforeExample:
class Example {
    void method() {
        throw new java.lang.RuntimeException();
    }
}

afterExample:
class Example {
    void method() {
        throw new java.lang.RuntimeException("Unnamed runtime exception");
    }
}

negativeExample:
class Example {
    void method() {
        throw new java.lang.IllegalArgumentException("Specific reason");
    }
    void anotherMethod() {
        throw new java.lang.RuntimeException("Already has a message");
    }
}
